#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <utility>
#include <string>
#include <iostream>
#include "Common.h"

class InstructionBase {
public:
enum Type {
    R, I, S, B, U, J
};

private:
    unsigned int opcode;
    unsigned int rs1;
    unsigned int rs2;
    unsigned int rd;
    unsigned int funct3;
    unsigned int funct7;
    Immediate imm;
    Instruction inst;
public:
    Type t;

    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(0), t(Type::R) {}

    InstructionBase(unsigned int instruction) : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(instruction), t(Type::R) {}

    static InstructionBase nop() {
        return InstructionBase(0xFFFFFFFF);
    }

    bool is_nop() const {
        return inst == 0xFFFFFFFF;
    }

    static unsigned int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static unsigned int expand_digit(unsigned int digit, int lo) {
        return digit ? (0xffffffff << lo) : 0;
    }

    bool is_valid(const std::string& key) {
        // Placeholder for validation logic
        return true; // Replace with actual validation
    }

    void verify(const std::string& key) {
        if (!is_valid(key)) {
            throw InvalidAccess();
        }
    }

    void debug() const {
        std::cout << "Opcode: " << opcode << std::endl;
        std::cout << "rs1: " << rs1 << std::endl;
        std::cout << "rs2: " << rs2 << std::endl;
        std::cout << "rd: " << rd << std::endl;
        std::cout << "funct3: " << funct3 << std::endl;
        std::cout << "funct7: " << funct7 << std::endl;
        std::cout << "imm: " << imm << std::endl;
        std::cout << "inst: " << inst << std::endl;
        std::cout << "Type: " << static_cast<int>(t) << std::endl;
    }

    bool has_op1() const {
        return false; // Placeholder
    }

    bool has_op2() const {
        return false; // Placeholder
    }
};

class InstructionR : public InstructionBase {
public:
    InstructionR(unsigned int inst) : InstructionBase(inst) {}
};

class InstructionI : public InstructionBase {
public:
    InstructionI(unsigned int inst) : InstructionBase(inst) {}
};

class InstructionS : public InstructionBase {
public:
    InstructionS(unsigned int inst) : InstructionBase(inst) {}
};

class InstructionB : public InstructionBase {
public:
    InstructionB(unsigned int inst) : InstructionBase(inst) {}
};

class InstructionU : public InstructionBase {
public:
    InstructionU(unsigned int inst) : InstructionBase(inst) {}
};

class InstructionJ : public InstructionBase {
public:
    InstructionJ(unsigned int inst) : InstructionBase(inst) {}
};

#endif // INSTRUCTION_HPP
